    C[0, 0] = C[1, 1] = C[2, 2] = lam + 2.0 * mu; C[3, 3] = C[4, 4] = C[5, 5] = mu
    q = 1.0 / np.sqrt(3.0); Ke = np.zeros((24, 24))
